text:
{
  "title_novice": "Почему рифы так ценны нефтяникам",
  "summary": [
    {
      "text": "Рифы составляют малую долю карбонатных отложений, но содержат порядка 10–12 % мировых запасов углеводородов.",
      "claims": ["c1", "c2"]
    },
    {
      "text": "При небольшой площади рифовые залежи бывают очень высокими, поэтому запасов на единицу площади много.",
      "claims": ["c3", "c4", "c5", "c6"]
    },
    {
      "text": "Из-за этого разработка рифовых залежей обладает высокой экономической эффективностью, и нефтяники интересуются рифами.",
      "claims": ["c7", "c8"]
    }
  ],
  "claims": [
    {
      "key": "c1",
      "text": "Рифы содержат порядка 10–12 % мировых запасов углеводородов.",
      "kind": "observation",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "они содержат порядка 10–12 % мировых запасов углеводородов",
      "numbers": ["10–12"],
      "question": null
    },
    {
      "key": "c2",
      "text": "Рифы составляют очень малую долю всех карбонатных отложений.",
      "kind": "observation",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "Составляя лишь очень малую долю карбонатных отложений вообще",
      "numbers": [],
      "question": null
    },
    {
      "key": "c3",
      "text": "При относительно небольшой площади высота залежей в рифах бывает очень значительной.",
      "kind": "observation",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "При относительно небольшой площади, высота залежей бывает очень значительной",
      "numbers": [],
      "question": null
    },
    {
      "key": "c4",
      "text": "Высота залежи месторождения Карачаганак превышает 1500 м.",
      "kind": "observation",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "высота залежи месторождения Карачаганак превышает 1500 м",
      "numbers": ["1500"],
      "question": null
    },
    {
      "key": "c5",
      "text": "На ряде месторождений зоны Ла Реформа в Мексике высота залежей колеблется в диапазоне 900–2100 м.",
      "kind": "observation",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "на ряде месторождений зоны Ла Реформа Мексики колеблется в диапазоне 900–2100 м",
      "numbers": ["900–2100"],
      "question": null
    },
    {
      "key": "c6",
      "text": "Большая высота залежи при малой площади определяет высокую плотность запасов.",
      "kind": "inference",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "Это определяет высокую плотность запасов",
      "numbers": [],
      "question": null
    },
    {
      "key": "c7",
      "text": "Высокая плотность запасов определяет высокую экономическую эффективность разработки таких залежей.",
      "kind": "inference",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "и высокую экономическую эффективность разработки таких залежей",
      "numbers": [],
      "question": null
    },
    {
      "key": "c8",
      "text": "Из-за этих свойств нефтяники особенно интересуются рифами.",
      "kind": "inference",
      "unit_id": "u-200-f60108",
      "page": 200,
      "quote": "Естественно поэтому повышенный интерес к рифам нефтяников",
      "numbers": [],
      "question": null
    }
  ],
  "mechanism": [
    {
      "text": "Залежь — это скопление нефти или газа. Её высота показывает, сколько углеводородов лежит над каждым квадратным метром площади.",
      "claims": [],
      "hypothesis": true
    },
    {
      "text": "При одинаковой площади более высокая залежь содержит больше углеводородов на единицу площади. Поэтому плотность запасов выше.",
      "claims": ["c3", "c6"],
      "hypothesis": true
    }
  ],
  "practice": [
    {
      "text": "Специалист сравнивает рифы по двум признакам: площади залежи и её высоте.",
      "claims": ["c3"],
      "hypothesis": true
    },
    {
      "text": "Затем он оценивает плотность запасов, то есть запасы, приходящиеся на единицу площади.",
      "claims": ["c6"],
      "hypothesis": true
    },
    {
      "text": "Высокая плотность запасов повышает экономическую эффективность разработки. По этому признаку решают, стоит ли осваивать залежь.",
      "claims": ["c7"],
      "hypothesis": true
    }
  ],
  "nuances": [
    {
      "text": "Цифра 10–12 % — ориентир, а не точная доля. Автор пишет «порядка» и относит её ко всем мировым запасам.",
      "claims": ["c1"],
      "hypothesis": false
    },
    {
      "text": "Слова «бывает очень значительной» означают, что высота велика не всегда, а во многих случаях.",
      "claims": ["c3"],
      "hypothesis": false
    },
    {
      "text": "Высоты 1500 м и 900–2100 м — примеры конкретных месторождений, а не общее правило для всех рифов.",
      "claims": ["c4", "c5"],
      "hypothesis": false
    },
    {
      "text": "Автор не объясняет здесь, почему залежи в рифах бывают высокими. Он приводит только цифры по месторождениям.",
      "claims": ["c4"],
      "hypothesis": false
    }
  ],
  "deeper": [
    {
      "title": "Высота залежи и размещение скважин",
      "text": "Высота залежи влияет на то, где бурить разведочные скважины. Подробности разобраны в узлах о разведке рифов.",
      "claims": [],
      "hypothesis": true
    }
  ],
  "procedure": [],
  "numbers_conditions": [
    {
      "text": "Доля рифов в мировых запасах углеводородов: порядка 10–12 %.",
      "claims": ["c1"]
    },
    {
      "text": "Высота залежи месторождения Карачаганак: более 1500 м.",
      "claims": ["c4"]
    },
    {
      "text": "Высота залежей на ряде месторождений зоны Ла Реформа (Мексика): 900–2100 м.",
      "claims": ["c5"]
    },
    {
      "text": "Условие: относительно небольшая площадь рифа при очень значительной высоте залежи.",
      "claims": ["c3"]
    }
  ],
  "terms_defined": [
    {
      "term": "залежь",
      "term_en": "hydrocarbon accumulation (pool)",
      "abbr": "",
      "definition": "Скопление нефти или газа в горной породе. В этом узле речь идёт о скоплении в теле рифа.",
      "claims": ["c4"]
    },
    {
      "term": "высота залежи",
      "term_en": "oil or gas column height",
      "abbr": "",
      "definition": "Вертикальный размер залежи в метрах. Книга приводит значения 900–2100 м и более 1500 м.",
      "claims": ["c3", "c4"]
    },
    {
      "term": "запасы",
      "term_en": "reserves",
      "abbr": "",
      "definition": "Количество нефти и газа, которое оценивают в недрах. Книга говорит о «мировых запасах углеводородов».",
      "claims": ["c1"]
    },
    {
      "term": "плотность запасов",
      "term_en": "reserve density",
      "abbr": "",
      "definition": "Запасы, приходящиеся на единицу площади. Высокая, когда залежь высокая при небольшой площади.",
      "claims": ["c6"]
    },
    {
      "term": "углеводороды",
      "term_en": "hydrocarbons",
      "abbr": "",
      "definition": "Химические соединения углерода и водорода; основа нефти и газа. Это общее определение, не из текста книги.",
      "claims": []
    }
  ],
